// Shared helpers for the parity tests (test/parity/*.json).
//
// These files are generated by tools/parity/dump.py from the Python
// implementation. Each parity test loads its module file, decodes the
// values and checks the Dart port against them.
import 'dart:convert';
import 'dart:io';

/// Decodes a parity-JSON value: `__date__`/`__datetime__` markers become
/// [DateTime], `__repr__` markers stay informational (unconvertible values
/// are never asserted).
Object? decodeParityValue(Object? value) {
  if (value is List) return value.map(decodeParityValue).toList();
  if (value is Map) {
    if (value.containsKey('__date__')) {
      return DateTime.parse(value['__date__'] as String);
    }
    if (value.containsKey('__datetime__')) {
      return DateTime.parse(value['__datetime__'] as String);
    }
    return value.map((k, v) => MapEntry(k as String, decodeParityValue(v)));
  }
  return value;
}

/// All `{fn, args, expected}` cases of one parity JSON file.
List<Map<String, Object?>> loadParityCases(String module) {
  final raw = File('test/parity/$module.json').readAsStringSync();
  final doc = jsonDecode(raw) as Map<String, Object?>;
  return (doc['cases'] as List)
      .map((c) => (c as Map).map((k, v) => MapEntry(k as String, v)))
      .toList();
}
